using IndieRun;
using System.IO;
using System.Reflection;
using System.Diagnostics;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Threading;
using System.Xml.Linq;

static class Program
{
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static T Copy<T>(T value)=>JsonSerializer.Deserialize<T>(JsonSerializer.Serialize(value))!;
    static void Hook(BackupEngine e,Action<string> hook)=>typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(e,hook);
    static object? Call(object o,string name,params object?[] args)=>o.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static void Set(object o,string name,object? value)=>o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string name)=>(T)o.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance)!.GetValue(o)!;
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Refuse(Action action){try{action();}catch(Exception ex) when(ex is IOException or InvalidDataException or UnauthorizedAccessException or ArgumentException){return;}throw new Exception("Expected refusal");}
    static Package Fixture(string folder)
    {
        var path=Path.Combine(folder,"input","Bundle");Directory.CreateDirectory(path);File.WriteAllText(Path.Combine(path,"Game.exe"),"generated fixture, do not run");
        foreach(var d in new[]{"Data","Comics","OtherGame","Scratch"}){Directory.CreateDirectory(Path.Combine(path,d));File.WriteAllText(Path.Combine(path,d,d=="OtherGame"?"Other.exe":"data.txt"),"fixture "+d);}
        Directory.CreateDirectory(Path.Combine(path,"Data","Empty"));return new(){IsReal=true,Registered=false,Id=Guid.NewGuid().ToString("N"),Source=path,DetectedRoot=path,SearchRoot=Path.Combine(folder,"input"),Folder="Bundle",Name="Bundle",Alias="작은 정원"};
    }
    static MainWindow Window(string folder,List<Package> packages,ScanSnapshot scan)
    {
        var w=new MainWindow();Set(w,"packages",packages);Set(w,"selected",packages[0]);Set(w,"snapshot",scan);Set(w,"source",Path.Combine(folder,"input"));Set(w,"searchLocations",new List<SearchLocation>{new(){Path=Path.Combine(folder,"input")}});Set(w,"destination",Path.Combine(folder,"library"));Set(w,"playerRoot",Path.Combine(folder,"library"));Set(w,"backupStorageRoot",Path.Combine(folder,"backups"));Set(w,"checkpoints",packages.Select(p=>WorkspaceReconciler.Capture(p,scan)).ToList());return w;
    }
    static IEnumerable<DependencyObject> Visual(DependencyObject root){yield return root;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++)foreach(var node in Visual(System.Windows.Media.VisualTreeHelper.GetChild(root,i)))yield return node;}
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    [STAThread]static int Main(string[] args)
    {
        if(args[0]=="--seed-demo")
        {
            DemoSetup.Initialize(args[1]);var doc=new WorkspaceStore(Path.Combine(args[1],"data","workspace.json")).Load().Document!;var service=new BackupEngine(doc.BackupRoot);var games=doc.Packages.Where(p=>p.Registered==true&&!p.IsRelatedContent).Take(2).ToList();foreach(var game in new[]{games[0],games[1],games[0]})service.CreateAsync(game,[]).GetAwaiter().GetResult();var job=service.ListJobs(false).Last();service.ConfirmExecution(job.Id,true);Console.WriteLine("SEEDED "+service.Inventory().Count);return 0;
        }
        if(args[0]=="--rename-child")
        {
            var service=new FolderRename(args[1]);service.Checkpoint=point=>{if(point==args[3]){Console.WriteLine("READY");Console.Out.Flush();Thread.Sleep(Timeout.Infinite);}};service.Commit(JsonSerializer.Deserialize<RenameRecord>(File.ReadAllText(args[2]))!);return 0;
        }
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(null);
        var root=Path.Combine(Path.GetFullPath(args[0]),"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> action){var path=Path.Combine(root,name);Directory.CreateDirectory(path);try{action(path);results.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,status="FAIL",error=ex.ToString()});Console.WriteLine("FAIL "+name+": "+ex.Message);}}
        (WorkspaceDocument Plan,TagCatalog Tags,PlayerDocument Play,Package Main,Package Second,Package Asset) Data(string folder)
        {
            var p=Fixture(folder);p.Registered=true;p.Contents.Add(new(){Path="Comics",Role="related",Alias="디지털 만화"});var other=Fixture(Path.Combine(folder,"second"));other.Registered=true;other.Alias="다른 게임";
            var assetPath=Path.Combine(folder,"input","SharedAtlas");Directory.CreateDirectory(assetPath);File.WriteAllText(Path.Combine(assetPath,"guide.txt"),"guide");var asset=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,IsContent=true,Registered=false,Source=assetPath,DetectedRoot=assetPath,SearchRoot=p.SearchRoot,Folder="SharedAtlas",Name="SharedAtlas"};p.RelatedFolders.Add(new(){Id=asset.Id,Source=asset.Source,Name=asset.Folder,Alias="공통 설정집"});other.RelatedFolders.Add(new(){Id=asset.Id,Source=asset.Source,Name=asset.Folder,Alias="공통 설정집"});var all=new List<Package>{p,other,asset};ContentLinks.Normalize(all);
            var scan=GameScanner.Scan(folder);LibraryStore.EnsureIdentity(p.Source,p.Id);LibraryStore.EnsureIdentity(other.Source,other.Id);scan=GameScanner.Scan(folder);var play=new PlayerDocument{Games=[new(){Id=p.Id,Executable="Game.exe",WorkingDirectory="Data",Arguments="--keep"},new(){Id=other.Id,Executable="Game.exe"}]};var tags=new TagCatalog();var plan=new WorkspaceDocument{SearchRoot=folder,SearchLocations=[new(){Path=folder}],Destination=Path.Combine(folder,"library"),BackupRoot=Path.Combine(folder,"backups"),Packages=all,Checkpoints=all.Select(p=>WorkspaceReconciler.Capture(p,scan)).ToList(),SelectedId=p.Id};return(plan,tags,play,p,other,asset);
        }

        BackupJob Backup(string folder,out BackupEngine engine){var p=Fixture(folder);engine=new(Path.Combine(folder,"backups"));return engine.CreateAsync(p,[]).GetAwaiter().GetResult();}
        void Manifest(BackupEngine e,BackupJob j)=>File.WriteAllText(Path.Combine(e.Root,j.Id,"manifest.json"),JsonSerializer.Serialize(j));
        void MoveRecord(BackupEngine e,BackupJob j,string state){var m=new MoveJob{BackupId=j.Id,Source=j.SourceRoot,Destination=Path.Combine(Path.GetDirectoryName(e.Root)!,"moved-game"),Status=state};var d=Path.Combine(e.Root,j.Id,"moves");Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,m.Id+".json"),JsonSerializer.Serialize(m));}
        void RestoreRecord(BackupEngine e,BackupJob j,string state){var r=new RestoreJob{BackupId=j.Id,Status=state};r.TargetContainer=Path.Combine(Path.GetDirectoryName(e.Root)!,"restore-"+r.Id);var d=Path.Combine(e.Root,j.Id,"restores");Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,r.Id+".json"),JsonSerializer.Serialize(r));}
        Test("delete-keeps-original-game-and-history",folder=>{var j=Backup(folder,out var e);MoveRecord(e,j,"Completed");var before=File.ReadAllText(Path.Combine(j.SourceRoot,"Data","data.txt"));e.DeleteBackups([j.Id]);Check(e.Load(j.Id).Status=="Deleted"&&!Directory.Exists(e.Payload(j)),"Payload remains");Check(File.ReadAllText(Path.Combine(j.SourceRoot,"Data","data.txt"))==before&&e.ListMoves(false).Count==1,"Source or history changed");});
        Test("delete-blocks-interrupted-move",folder=>{var j=Backup(folder,out var e);MoveRecord(e,j,"Interrupted");Check(!e.Inventory().Single().Selectable,"Recovery backup selectable");Refuse(()=>e.DeleteBackups([j.Id]));Check(Directory.Exists(e.Payload(j)),"Protected payload removed");});
        Test("delete-blocks-unfinished-restore",folder=>{var j=Backup(folder,out var e);RestoreRecord(e,j,"Failed");Refuse(()=>e.DeleteBackups([j.Id]));Check(e.Inventory().Single().Protection!.Contains("복원"),"No explanation");});
        Test("batch-delete-preflights-entire-selection",folder=>{var a=Backup(Path.Combine(folder,"a"),out var e);var p=Fixture(Path.Combine(folder,"b"));var b=e.CreateAsync(p,[]).GetAwaiter().GetResult();RestoreRecord(e,b,"Interrupted");Refuse(()=>e.DeleteBackups([a.Id,b.Id]));Check(Directory.Exists(e.Payload(a))&&e.Load(a.Id).Status=="Completed","Partial batch before preflight");});
        Test("delete-respects-operation-lock",folder=>{var j=Backup(folder,out var e);using(var hold=new FileStream(Path.Combine(e.Root,"operation.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None)){Refuse(()=>e.DeleteBackups([j.Id]));}Check(e.Load(j.Id).Status=="Completed","Lock bypassed");});
        Test("delete-handles-readonly-backup-files",folder=>{var j=Backup(folder,out var e);File.SetAttributes(Path.Combine(e.Payload(j),"Game.exe"),FileAttributes.ReadOnly);e.DeleteBackups([j.Id]);Check(e.Load(j.Id).Status=="Deleted","Readonly deletion failed");});
        Test("locked-file-deletion-remains-retryable",folder=>{var j=Backup(folder,out var e);using(var hold=new FileStream(Path.Combine(e.Payload(j),"Data","data.txt"),FileMode.Open,FileAccess.Read,FileShare.None)){Refuse(()=>e.DeleteBackups([j.Id]));Check(e.Load(j.Id).Status=="DeleteFailed","No retry state");}e.DeleteBackups([j.Id]);Check(e.Load(j.Id).Status=="Deleted"&&Directory.Exists(j.SourceRoot),"Retry damaged original");});
        Test("delete-intent-interruption-is-retryable",folder=>{var j=Backup(folder,out var e);Hook(e,point=>{if(point=="delete-intent")throw new OperationCanceledException();});try{e.DeleteBackups([j.Id]);throw new Exception("Expected interruption");}catch(OperationCanceledException){}Check(e.Load(j.Id).Status=="Deleting","Intent absent");Hook(e,_=>{});e.DeleteBackups([j.Id]);Check(e.Load(j.Id).Status=="Deleted","Intent recovery failed");});
        Test("deleted-backup-cannot-be-verified-resumed-or-moved",folder=>{var j=Backup(folder,out var e);e.DeleteBackups([j.Id]);Refuse(()=>e.VerifyAsync(j.Id).GetAwaiter().GetResult());Refuse(()=>e.ResumeAsync(j.Id).GetAwaiter().GetResult());Refuse(()=>e.MoveAsync(j.Id,Path.Combine(folder,"target")).GetAwaiter().GetResult());Check(e.Load(j.Id).Status=="Deleted","Tombstone overwritten");});
        Test("deleted-backup-undo-refused-without-changing-move",folder=>{var j=Backup(folder,out var e);MoveRecord(e,j,"Completed");var m=e.ListMoves(false).Single();e.DeleteBackups([j.Id]);Refuse(()=>e.UndoMoveAsync(j.Id,m.Id).GetAwaiter().GetResult());Check(e.ListMoves(false).Single().Status=="Completed","History corrupted");});
        Test("execution-confirmation-is-manual-and-reversible",folder=>{var j=Backup(folder,out var e);Check(e.Load(j.Id).ExecutionConfirmedUtc==null,"Automatically confirmed");e.ConfirmExecution(j.Id,true);Check(e.Load(j.Id).ExecutionConfirmedUtc.HasValue,"Manual confirmation lost");e.ConfirmExecution(j.Id,false);Check(!e.Load(j.Id).ExecutionConfirmedUtc.HasValue,"Clear failed");e.DeleteBackups([j.Id]);Refuse(()=>e.ConfirmExecution(j.Id,true));});
        Test("inventory-reports-actual-stored-and-reclaimable-bytes",folder=>{var j=Backup(folder,out var e);var i=e.Inventory().Single();Check(i.ReclaimableBytes==j.TotalBytes&&i.StoredBytes>i.ReclaimableBytes,"Wrong space accounting");e.DeleteBackups([j.Id]);i=e.Inventory().Single();Check(i.ReclaimableBytes==0&&i.StoredBytes>0&&!i.Selectable,"History not accounted");});
        Test("incomplete-backup-is-protected",folder=>{var j=Backup(folder,out var e);j.Status="Interrupted";Manifest(e,j);Refuse(()=>e.DeleteBackups([j.Id]));Check(!e.Inventory().Single().Selectable,"Incomplete backup selected");});
        Test("preview-prioritizes-readme-and-respects-independent-scope",folder=>{var f=Data(folder);File.WriteAllText(Path.Combine(f.Main.Source,"readme.txt"),"read me");File.WriteAllText(Path.Combine(f.Main.Source,"OtherGame","hidden.txt"),"independent");f.Main.OmittedFolders.Add("OtherGame");var files=PreviewFiles.Candidates(f.Main,GameScanner.Scan(folder));Check(Path.GetFileName(files[0].Path)=="readme.txt"&&!files.Any(x=>x.Path.Contains("hidden.txt"))&&files.Any(x=>GameScanner.Within(x.Path,f.Asset.Source))&&!files.Any(x=>Path.GetFileName(x.Path).StartsWith(".indierun")),"Bad candidate scope/order");});
        string ImageFixture(string folder){var path=Path.Combine(folder,"cover.png");var pixels=Enumerable.Repeat((byte)160,12*8*3).ToArray();var image=System.Windows.Media.Imaging.BitmapSource.Create(12,8,96,96,System.Windows.Media.PixelFormats.Rgb24,null,pixels,36);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(image));using(var output=File.Create(path))encoder.Save(output);return path;}
        Test("card-artwork-copy-preserves-source-and-loads-thumbnail",folder=>{var path=ImageFixture(folder);var before=File.ReadAllBytes(path);var stored=PreviewFiles.CopyArtwork(path,Path.Combine(folder,"library"));Check(stored.StartsWith(".indierun-art/")&&File.ReadAllBytes(Path.Combine(folder,"library",stored)).SequenceEqual(before)&&File.ReadAllBytes(path).SequenceEqual(before),"Source changed");Check(PreviewFiles.Image(path,128).IsFrozen,"Thumbnail crosses thread unfrozen");});
        Test("invalid-artwork-is-not-persisted",folder=>{var path=Path.Combine(folder,"fake.png");File.WriteAllText(path,"not an image");try{PreviewFiles.CopyArtwork(path,Path.Combine(folder,"library"));throw new Exception("Invalid image accepted");}catch(Exception ex)when(ex is NotSupportedException or IOException or FormatException){}Check(!Directory.Exists(Path.Combine(folder,"library",".indierun-art")),"Invalid artwork saved");});
        SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        foreach(var size in new[]{(820d,560d),(1000d,720d)})Test("preview-and-manager-layout-"+size.Item1,folder=>{var f=Data(folder);var w=Window(folder,f.Plan.Packages,GameScanner.Scan(folder));Window? preview=null,manager=null;try{new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();preview=(Window)Call(w,"BuildPreview",f.Main,GameScanner.Scan(folder))!;manager=(Window)Call(w,"BuildBackupManager")!;foreach(var dialog in new[]{preview,manager}){var body=(FrameworkElement)dialog.Content;body.Measure(new Size(size.Item1,size.Item2));body.Arrange(new Rect(0,0,size.Item1,size.Item2));body.UpdateLayout();var controls=Visual(body).OfType<Button>().Where(b=>b.IsVisible).ToList();Check(controls.All(b=>b.ActualWidth<2||b.TranslatePoint(new Point(),body).X+b.ActualWidth<=body.ActualWidth+1),"Action clipped horizontally");Check(System.Windows.Input.KeyboardNavigation.GetTabNavigation(dialog)==System.Windows.Input.KeyboardNavigationMode.Cycle,"Tab navigation not confined");}}finally{preview?.Close();manager?.Close();Close(w);}});
        Test("modal-focus-tab-and-escape-respect-unsaved-close-guard",folder=>{var f=Data(folder);var w=Window(folder,f.Plan.Packages,GameScanner.Scan(folder));Window? preview=null;try{new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();preview=(Window)Call(w,"BuildPreview",f.Main,GameScanner.Scan(folder))!;preview.Show();Wait(Task.Delay(180));var search=Visual((DependencyObject)preview.Content).OfType<TextBox>().Single(t=>System.Windows.Automation.AutomationProperties.GetName(t)=="내용 파일 검색");Check(System.Windows.Input.Keyboard.FocusedElement==search,"Initial focus not on search");search.MoveFocus(new System.Windows.Input.TraversalRequest(System.Windows.Input.FocusNavigationDirection.Next));Check(System.Windows.Input.Keyboard.FocusedElement is ComboBox,"Tab did not reach folder selector");var protect=true;preview.Closing+=(_,e)=>{if(protect)e.Cancel=true;};void Escape(){preview.RaiseEvent(new System.Windows.Input.KeyEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,PresentationSource.FromVisual(preview)!,0,System.Windows.Input.Key.Escape){RoutedEvent=System.Windows.Input.Keyboard.PreviewKeyDownEvent});}Escape();Check(preview.IsVisible,"Close guard bypassed");protect=false;Escape();Check(!preview.IsVisible,"Escape did not close");}finally{preview?.Close();Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{root,total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"RESULT {results.Count-failed}/{results.Count}");return failed==0?0:1;
    }
}


